sp_widget.client_script:
api.controller = function($timeout) {

  var c = this;


  /* =========================================================
     TRAINER
     ========================================================= */

  c.trainerId =
    (
      c.data.trainer &&
      c.data.trainer.id
    )
      ? c.data.trainer.id
      : '';


  /* =========================================================
     SIDEBAR
     ========================================================= */

  var sidebarKey =
    'campus360_trainer_sidebar_collapsed';


  c.sidebarCollapsed =
    localStorage.getItem(
      sidebarKey
    ) === 'true';


  c.toggleSidebar =
    function() {

      c.sidebarCollapsed =
        !c.sidebarCollapsed;


      localStorage.setItem(
        sidebarKey,
        c.sidebarCollapsed
          ? 'true'
          : 'false'
      );

    };


  /* =========================================================
     COPY SERVER DATA
     ========================================================= */

  function copyData(
    d
  ) {

    if (!d) {

      return;

    }


    c.data.metrics =
      d.metrics ||
      c.data.metrics;


    c.data.availableSlots =
      d.availableSlots ||
      [];


    c.data.requests =
      d.requests ||
      [];


    c.data.scheduledInterviews =
      d.scheduledInterviews ||
      [];


    c.data.feedbackPending =
      d.feedbackPending ||
      [];


    c.data.error =
      d.error ||
      '';

  }


  /* =========================================================
     REFRESH
     ========================================================= */

  c.refresh =
    function() {

      c.server.get({

        action:
          'refresh',

        trainer:
          c.trainerId

      }).then(
        function(response) {

          if (
            response &&
            response.data
          ) {

            copyData(
              response.data
            );

          }

        }
      );

    };


  /* =========================================================
     CREATE SLOT
     ========================================================= */

  c.createSlotModalOpen =
    false;

  c.savingSlot =
    false;

  c.slotFormError =
    '';


  c.slotForm = {};


  c.openCreateSlot =
    function() {

      c.slotFormError =
        '';


      c.slotForm = {

        interviewType:
          'Technical',

        skillArea:
          '',

        availableDate:
          new Date(),

        startTime:
          null,

        endTime:
          null

      };


      c.createSlotModalOpen =
        true;

    };


  c.closeCreateSlot =
    function() {

      c.createSlotModalOpen =
        false;


      c.slotFormError =
        '';

    };


  c.createSlot =
    function() {

      c.slotFormError =
        '';


      if (
        !c.slotForm.interviewType
      ) {

        c.slotFormError =
          'Select Interview Type.';

        return;

      }


      if (
        !c.slotForm.availableDate
      ) {

        c.slotFormError =
          'Select Available Date.';

        return;

      }


      if (
        !c.slotForm.startTime ||
        !c.slotForm.endTime
      ) {

        c.slotFormError =
          'Start Time and End Time are required.';

        return;

      }


      var start =
        toTime(
          c.slotForm.startTime
        );


      var end =
        toTime(
          c.slotForm.endTime
        );


      if (
        !start ||
        !end
      ) {

        c.slotFormError =
          'Enter valid times.';

        return;

      }


      if (
        minutes(end) <=
        minutes(start)
      ) {

        c.slotFormError =
          'End Time must be after Start Time.';

        return;

      }


      c.savingSlot =
        true;


      c.server.get({

        action:
          'create_slot',

        trainer:
          c.trainerId,

        interviewType:
          c.slotForm.interviewType,

        skillArea:
          c.slotForm.skillArea,

        availableDate:
          toDate(
            c.slotForm.availableDate
          ),

        startTime:
          start,

        endTime:
          end

      }).then(
        function(response) {

          c.savingSlot =
            false;


          var d =
            response &&
            response.data
              ? response.data
              : null;


          if (
            d &&
            d.slotSuccess
          ) {

            copyData(
              d
            );


            c.createSlotModalOpen =
              false;


            c.showBanner(
              d.slotMessage,
              'success'
            );

          } else {

            c.slotFormError =
              (
                d &&
                d.slotMessage
              ) ||
              'Unable to create slot.';

          }

        }
      );

    };


  /* =========================================================
     ACCEPT REQUEST
     ========================================================= */

  c.processingId =
    '';


  c.acceptRequest =
    function(
      request
    ) {

      if (
        !request ||
        !request.sys_id
      ) {

        return;

      }


      c.processingId =
        request.sys_id;


      c.server.get({

        action:
          'accept_request',

        trainer:
          c.trainerId,

        request:
          request.sys_id

      }).then(
        function(response) {

          c.processingId =
            '';


          var d =
            response &&
            response.data
              ? response.data
              : null;


          if (
            d &&
            d.acceptSuccess
          ) {

            copyData(
              d
            );


            c.showBanner(
              d.acceptMessage,
              'success'
            );

          } else {

            c.showBanner(
              (
                d &&
                d.acceptMessage
              ) ||
              'Unable to accept the request.',
              'error'
            );

          }

        }
      );

    };


  /* =========================================================
     INTERVIEW DETAILS
     ========================================================= */

  c.interviewDetailsOpen =
    false;


  c.selectedInterview =
    {};


  /* =========================================================
     INTERVIEW STATUS DROPDOWN
     ========================================================= */

  c.selectedInterviewStatus =
    'Scheduled';


  c.interviewStatusOptions = [

    {
      value:
        'Scheduled',

      label:
        'Scheduled'
    },

    {
      value:
        'Completed',

      label:
        'Completed'
    }

  ];


  c.detailError =
    '';


  c.openInterviewDetails =
    function(
      session
    ) {

      if (!session) {

        return;

      }


      c.selectedInterview =
        session;


      c.selectedInterviewStatus =
        session.interviewStatus ||
        'Scheduled';


      c.detailError =
        '';


      c.interviewDetailsOpen =
        true;

    };


  c.closeInterviewDetails =
    function() {

      c.interviewDetailsOpen =
        false;


      c.selectedInterview =
        {};


      c.selectedInterviewStatus =
        'Scheduled';


      c.detailError =
        '';

    };


  /* =========================================================
     QR VERIFICATION
     Existing functionality retained.
     ========================================================= */

  c.verifyModalOpen =
    false;


  c.verifySession =
    {};


  c.verifyToken =
    '';


  c.verifyError =
    '';


  c.verifyingQR =
    false;


  c.openVerifyModal =
    function(
      session
    ) {

      c.verifySession =
        session ||
        c.selectedInterview;


      c.verifyToken =
        '';


      c.verifyError =
        '';


      c.verifyModalOpen =
        true;

    };


  c.closeVerifyModal =
    function() {

      c.verifyModalOpen =
        false;


      c.verifySession =
        {};


      c.verifyToken =
        '';


      c.verifyError =
        '';

    };


  c.verifyQR =
    function() {

      c.verifyError =
        '';


      if (
        !c.verifyToken ||
        !String(
          c.verifyToken
        ).trim()
      ) {

        c.verifyError =
          'Enter the QR token.';

        return;

      }


      if (
        !c.verifySession ||
        !c.verifySession.sys_id
      ) {

        c.verifyError =
          'Interview session is missing.';

        return;

      }


      c.verifyingQR =
        true;


      c.server.get({

        action:
          'verify_qr',

        trainer:
          c.trainerId,

        interview:
          c.verifySession.sys_id,

        token:
          String(
            c.verifyToken
          ).trim()

      }).then(
        function(response) {

          c.verifyingQR =
            false;


          var d =
            response &&
            response.data
              ? response.data
              : null;


          if (
            d &&
            d.verifySuccess
          ) {

            copyData(
              d
            );


            c.verifyModalOpen =
              false;


            c.showBanner(
              d.verifyMessage,
              'success'
            );


            updateSelectedInterview(
              c.verifySession.sys_id
            );

          } else {

            c.verifyError =
              (
                d &&
                d.verifyMessage
              ) ||
              'QR verification failed.';

          }

        }
      );

    };


  function updateSelectedInterview(
    sysId
  ) {

    var list =
      c.data.scheduledInterviews ||
      [];


    for (
      var i = 0;
      i < list.length;
      i++
    ) {

      if (
        list[i].sys_id ==
        sysId
      ) {

        c.selectedInterview =
          list[i];


        c.selectedInterviewStatus =
          list[i].interviewStatus ||
          'Scheduled';


        return;

      }

    }

  }


  /* =========================================================
     MARK INTERVIEW COMPLETED
     ========================================================= */

  c.completingInterview =
    false;


  c.markInterviewCompleted =
    function(
      session
    ) {

      if (
        !session ||
        !session.sys_id
      ) {

        return;

      }


      /*
       * Only the dropdown selection is required here.
       *
       * QR was already scanned in the existing workflow,
       * so there is intentionally NO second QR check.
       */

      if (
        c.selectedInterviewStatus !=
        'Completed'
      ) {

        c.detailError =
          'Select Completed from the Interview Status dropdown.';

        return;

      }


      c.completingInterview =
        true;


      c.detailError =
        '';


      /*
       * Send the selected status to the server.
       */

      c.server.get({

        action:
          'mark_completed',

        trainer:
          c.trainerId,

        interview:
          session.sys_id,

        status:
          c.selectedInterviewStatus

      }).then(
        function(response) {

          c.completingInterview =
            false;


          var d =
            response &&
            response.data
              ? response.data
              : null;


          if (
            d &&
            d.completeSuccess
          ) {

            /*
             * Reload all data.
             *
             * Since Scheduled list queries only
             * Interview Status = Scheduled,
             * this interview disappears from
             * Scheduled Interviews.
             *
             * Feedback page/query can now see
             * Interview Status = Completed.
             */

            copyData(
              d
            );


            c.interviewDetailsOpen =
              false;


            c.selectedInterview =
              {};


            c.selectedInterviewStatus =
              'Scheduled';


            c.showBanner(
              d.completeMessage,
              'success'
            );

          } else {

            c.detailError =
              (
                d &&
                d.completeMessage
              ) ||
              'Unable to complete interview.';

          }

        }
      );

    };


  /* =========================================================
     FEEDBACK
     ========================================================= */

  c.feedbackModalOpen =
    false;


  c.feedbackSession =
    {};


  c.feedbackError =
    '';


  c.savingFeedback =
    false;


  c.feedbackForm =
    {};


  c.openFeedbackModal =
    function(
      session
    ) {

      if (!session) {

        return;

      }


      c.feedbackSession =
        session;


      c.feedbackError =
        '';


      c.feedbackForm = {

        technicalScore:
          null,

        communicationScore:
          null,

        problemSolvingScore:
          null,

        strengths:
          '',

        improvementAreas:
          '',

        recommendation:
          ''

      };


      c.feedbackModalOpen =
        true;

    };


  c.closeFeedbackModal =
    function() {

      c.feedbackModalOpen =
        false;


      c.feedbackSession =
        {};


      c.feedbackError =
        '';

    };


  c.getOverallPreview =
    function() {

      var technical =
        parseScore(
          c.feedbackForm.technicalScore
        );


      var communication =
        parseScore(
          c.feedbackForm.communicationScore
        );


      var problem =
        parseScore(
          c.feedbackForm.problemSolvingScore
        );


      if (
        technical === null ||
        communication === null ||
        problem === null
      ) {

        return '—';

      }


      return Math.round(
        (
          technical +
          communication +
          problem
        ) / 3
      );

    };


  c.submitFeedback =
    function() {

      var technical =
        parseScore(
          c.feedbackForm.technicalScore
        );


      var communication =
        parseScore(
          c.feedbackForm.communicationScore
        );


      var problem =
        parseScore(
          c.feedbackForm.problemSolvingScore
        );


      if (
        technical === null ||
        communication === null ||
        problem === null
      ) {

        c.feedbackError =
          'Enter all scores from 0 to 100.';

        return;

      }


      c.savingFeedback =
        true;


      c.feedbackError =
        '';


      c.server.get({

        action:
          'submit_feedback',

        trainer:
          c.trainerId,

        interview:
          c.feedbackSession.sys_id,

        technicalScore:
          technical,

        communicationScore:
          communication,

        problemSolvingScore:
          problem,

        strengths:
          c.feedbackForm.strengths,

        improvementAreas:
          c.feedbackForm.improvementAreas,

        recommendation:
          c.feedbackForm.recommendation

      }).then(
        function(response) {

          c.savingFeedback =
            false;


          var d =
            response &&
            response.data
              ? response.data
              : null;


          if (
            d &&
            d.feedbackSuccess
          ) {

            copyData(
              d
            );


            c.feedbackModalOpen =
              false;


            c.showBanner(
              d.feedbackMessage,
              'success'
            );

          } else {

            c.feedbackError =
              (
                d &&
                d.feedbackMessage
              ) ||
              'Unable to save feedback.';

          }

        }
      );

    };


  /* =========================================================
     BANNER
     ========================================================= */

  c.bannerMessage =
    '';


  c.bannerType =
    '';


  c.showBanner =
    function(
      message,
      type
    ) {

      c.bannerMessage =
        message || '';


      c.bannerType =
        type || 'success';


      $timeout(
        function() {

          c.bannerMessage =
            '';

        },
        4000
      );

    };


  /* =========================================================
     HELPERS
     ========================================================= */

  function toDate(
    value
  ) {

    var d =
      value instanceof Date
        ? value
        : new Date(value);


    var month =
      String(
        d.getMonth() + 1
      );


    var day =
      String(
        d.getDate()
      );


    if (
      month.length == 1
    ) {

      month =
        '0' + month;

    }


    if (
      day.length == 1
    ) {

      day =
        '0' + day;

    }


    return (
      d.getFullYear() +
      '-' +
      month +
      '-' +
      day
    );

  }


  function toTime(
    value
  ) {

    if (!value) {

      return '';

    }


    if (
      value instanceof Date
    ) {

      var hours =
        String(
          value.getHours()
        );


      var minutesValue =
        String(
          value.getMinutes()
        );


      if (
        hours.length == 1
      ) {

        hours =
          '0' + hours;

      }


      if (
        minutesValue.length == 1
      ) {

        minutesValue =
          '0' +
          minutesValue;

      }


      return (
        hours +
        ':' +
        minutesValue +
        ':00'
      );

    }


    var text =
      String(
        value
      );


    if (
      text.length == 5
    ) {

      return text +
        ':00';

    }


    return text.substring(
      0,
      8
    );

  }


  function minutes(
    value
  ) {

    if (!value) {

      return 0;

    }


    var parts =
      String(
        value
      ).split(':');


    return (
      parseInt(
        parts[0],
        10
      ) * 60
      +
      parseInt(
        parts[1],
        10
      )
    );

  }


  function parseScore(
    value
  ) {

    if (
      value === null ||
      typeof value === 'undefined' ||
      value === ''
    ) {

      return null;

    }


    var number =
      parseInt(
        value,
        10
      );


    if (
      isNaN(number) ||
      number < 0 ||
      number > 100
    ) {

      return null;

    }


    return number;

  }

};

sp_widget.css:
/* =========================================================
   CAMPUS360 TRAINER
   MOCK INTERVIEW SLOTS
   FULL VIEW / DASHBOARD NAVBAR STYLE
   ========================================================= */


/* =========================================================
   GLOBAL RESET
   ========================================================= */

html,
body {

  width: 100% !important;

  height: 100% !important;

  min-width: 100% !important;

  min-height: 100% !important;

  margin: 0 !important;

  padding: 0 !important;

  overflow: hidden !important;

}


body {

  background: #f3f6fb !important;

}


/* =========================================================
   SERVICENOW OUTER CONTAINER RESET
   ========================================================= */

.container:has(.campus360-slot-app),
.container-fluid:has(.campus360-slot-app),
.row:has(.campus360-slot-app),
[class*="col-"]:has(.campus360-slot-app),
.well:has(.campus360-slot-app),
.panel:has(.campus360-slot-app) {

  width: 100% !important;

  max-width: none !important;

  margin: 0 !important;

  padding: 0 !important;

  border: 0 !important;

  background: transparent !important;

  box-shadow: none !important;

}


/* =========================================================
   FULL CAMPUS360 APPLICATION
   ========================================================= */

.campus360-slot-app {

  position: fixed !important;

  top: 0 !important;

  left: 0 !important;

  right: 0 !important;

  bottom: 0 !important;

  width: 100vw !important;

  height: 100vh !important;

  min-width: 100vw !important;

  min-height: 100vh !important;

  max-width: 100vw !important;

  max-height: 100vh !important;

  margin: 0 !important;

  padding: 0 !important;

  z-index: 2147483647 !important;

  display: flex !important;

  flex-direction: row !important;

  overflow: hidden !important;

  isolation: isolate;

  background:
    radial-gradient(
      circle at 8% 8%,
      rgba(239,231,255,.52),
      transparent 24%
    ),
    radial-gradient(
      circle at 94% 8%,
      rgba(232,247,255,.55),
      transparent 25%
    ),
    #f3f6fb;

  color: #17233c;

  font-family:
    "Inter",
    "Segoe UI",
    Arial,
    sans-serif;

  -webkit-font-smoothing: antialiased;

}


.campus360-slot-app,
.campus360-slot-app * {

  box-sizing: border-box;

}


/* =========================================================
   SIDEBAR - DARK PURPLE
   ========================================================= */

.campus360-slot-sidebar {

  position: relative !important;

  top: 0 !important;

  left: 0 !important;

  bottom: auto !important;

  width: 264px !important;

  min-width: 264px !important;

  max-width: 264px !important;

  height: 100vh !important;

  min-height: 100vh !important;

  max-height: 100vh !important;

  flex: 0 0 264px;

  display: flex;

  flex-direction: column;

  overflow: hidden;

  z-index: 50;

  background:
    linear-gradient(
      180deg,
      #130d2f 0%,
      #160d38 48%,
      #100a29 100%
    ) !important;

  border-right:
    1px solid
    #2d2157 !important;

  box-shadow:
    5px
    0
    18px
    rgba(10,7,25,.20);

  transition:
    width .25s ease,
    min-width .25s ease,
    max-width .25s ease,
    flex-basis .25s ease;

}


/* =========================================================
   SIDEBAR COLLAPSED
   ========================================================= */

.campus360-slot-app.sidebar-collapsed
.campus360-slot-sidebar {

  width: 76px !important;

  min-width: 76px !important;

  max-width: 76px !important;

  flex-basis: 76px;

}


/* =========================================================
   BRAND
   ========================================================= */

.slot-brand {

  width: 100%;

  height: 99px;

  min-height: 99px;

  padding:
    0
    15px;

  display: flex;

  align-items: center;

  gap: 13px;

  flex-shrink: 0;

  border-bottom:
    1px solid
    #2d2157 !important;

  background:
    linear-gradient(
      135deg,
      #170e38,
      #1c1045
    ) !important;

}


.slot-brand-mark {

  width: 49px;

  height: 49px;

  flex: 0 0 49px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 14px;

  background:
    linear-gradient(
      135deg,
      #704cf4,
      #563dd5
    );

  color: #ffffff;

  font-size: 23px;

  box-shadow:
    0
    8px
    19px
    rgba(91,70,230,.30);

}


.slot-brand-text {

  min-width: 0;

}


.slot-brand-text strong {

  display: block;

  color: #ffffff !important;

  font-size: 20px;

  line-height: 1;

  font-weight: 950;

}


.slot-brand-text span {

  display: block;

  margin-top: 5px;

  color: #b9abd8 !important;

  font-size: 10px;

  line-height: 1;

  font-weight: 900;

  letter-spacing: 1.25px;

}


/* =========================================================
   SIDEBAR TRAINER PROFILE
   ========================================================= */

.slot-trainer-profile {

  margin:
    18px
    7px
    13px;

  min-height: 70px;

  padding:
    11px;

  display: flex;

  align-items: center;

  gap: 10px;

  flex-shrink: 0;

  border:
    1px solid
    #4b3475 !important;

  border-radius: 13px;

  background:
    linear-gradient(
      135deg,
      #211342,
      #29164f
    ) !important;

  text-decoration: none !important;

}


.slot-avatar {

  width: 44px;

  height: 44px;

  flex: 0 0 44px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  background:
    linear-gradient(
      135deg,
      #704cf4,
      #5544d2
    );

  color: #ffffff;

  font-size: 12px;

  font-weight: 950;

}


.slot-trainer-info {

  min-width: 0;

  flex: 1;

}


.slot-trainer-info strong {

  display: block;

  overflow: hidden;

  color: #ffffff !important;

  font-size: 12px;

  line-height: 1.2;

  font-weight: 950;

  white-space: nowrap;

  text-overflow: ellipsis;

}


.slot-trainer-info span {

  display: block;

  margin-top: 3px;

  color: #b9abd8 !important;

  font-size: 9px;

  font-weight: 800;

}


.slot-profile-arrow {

  color: #a99bc7 !important;

  font-size: 19px;

}


/* =========================================================
   SIDEBAR NAVIGATION
   ========================================================= */

.slot-nav {

  flex: 1 1 auto;

  min-height: 0;

  overflow-y: auto;

  overflow-x: hidden;

  padding:
    0
    5px
    18px;

}


/* Hide sidebar scrollbar */
.slot-nav::-webkit-scrollbar {

  width: 0;

  height: 0;

}


.slot-nav {

  scrollbar-width: none;

  -ms-overflow-style: none;

}


.slot-nav-label {

  margin:
    19px
    7px
    7px;

  color: #9283b6 !important;

  font-size: 10px;

  line-height: 1;

  font-weight: 950;

  letter-spacing: 1.1px;

}


.slot-nav-item {

  position: relative;

  width: 100%;

  min-height: 47px;

  margin:
    2px
    0;

  padding:
    0
    10px;

  display: flex;

  align-items: center;

  gap: 10px;

  border-radius: 10px;

  color: #c4b8dc !important;

  background: transparent !important;

  text-decoration: none !important;

  font-size: 13px;

  line-height: 1.25;

  font-weight: 850;

  transition:
    background .18s ease,
    color .18s ease;

}


.slot-nav-item:hover {

  background: rgba(124,58,237,.18) !important;

  color: #ffffff !important;

}


.slot-nav-item.active {

  background:
    linear-gradient(
      90deg,
      #7c3aed 0%,
      #8b3ff2 100%
    ) !important;

  color: #ffffff !important;

  font-weight: 950;

  box-shadow: none !important;

}


.slot-nav-item.active:before {

  content: "";

  position: absolute;

  left: 0;

  top: 5px;

  bottom: 5px;

  width: 4px;

  border-radius:
    0
    5px
    5px
    0;

  background: #a78bfa !important;

}


.slot-nav-icon {

  width: 28px;

  min-width: 28px;

  height: 28px;

  display: flex;

  align-items: center;

  justify-content: center;

  color: #a99ac8 !important;

  font-size: 17px;

}


.slot-nav-item:hover
.slot-nav-icon {

  color: #ffffff !important;

}


.slot-nav-item.active
.slot-nav-icon {

  color: #ffffff !important;

}


.slot-nav-text {

  min-width: 0;

  flex: 1;

}


.slot-nav-count {

  min-width: 22px;

  height: 22px;

  margin-left: auto;

  padding:
    0
    6px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 50%;

  background: #3a2764 !important;

  color: #d9ceef !important;

  font-size: 9px;

  font-weight: 950;

}


.slot-nav-item.active
.slot-nav-count {

  background: rgba(255,255,255,.18) !important;

  color: #ffffff !important;

}


/* =========================================================
   COLLAPSED SIDEBAR CONTENT
   ========================================================= */

.campus360-slot-app.sidebar-collapsed
.slot-brand {

  padding-left: 0;

  padding-right: 0;

  justify-content: center;

}


.campus360-slot-app.sidebar-collapsed
.slot-brand-text,

.campus360-slot-app.sidebar-collapsed
.slot-trainer-info,

.campus360-slot-app.sidebar-collapsed
.slot-profile-arrow,

.campus360-slot-app.sidebar-collapsed
.slot-nav-label,

.campus360-slot-app.sidebar-collapsed
.slot-nav-text,

.campus360-slot-app.sidebar-collapsed
.slot-nav-count {

  display: none !important;

}


.campus360-slot-app.sidebar-collapsed
.slot-trainer-profile {

  margin-left: 9px;

  margin-right: 9px;

  justify-content: center;

}


.campus360-slot-app.sidebar-collapsed
.slot-nav-item {

  justify-content: center;

  padding-left: 0;

  padding-right: 0;

}


/* =========================================================
   MAIN
   ========================================================= */

.campus360-slot-main {

  position: relative;

  width:
    calc(100vw - 264px) !important;

  max-width:
    calc(100vw - 264px) !important;

  min-width: 0 !important;

  height: 100vh !important;

  min-height: 100vh !important;

  max-height: 100vh !important;

  margin: 0 !important;

  padding: 0 !important;

  flex:
    1 1 auto;

  overflow-x: hidden !important;

  overflow-y: auto !important;

  background: #f3f6fb;

  transition:
    width .25s ease,
    max-width .25s ease;

}


.campus360-slot-app.sidebar-collapsed
.campus360-slot-main {

  width:
    calc(100vw - 76px) !important;

  max-width:
    calc(100vw - 76px) !important;

}


/* =========================================================
   TOP NAVBAR
   ========================================================= */

.slot-topbar {

  position: sticky;

  top: 0;

  z-index: 100;

  width: 100%;

  height: 74px;

  min-height: 74px;

  padding:
    0
    19px
    0
    23px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  background:
    linear-gradient(
      90deg,
      #ffffff,
      #fbfdff
    );

  border-bottom:
    1px solid
    #dce4ec;

  box-shadow:
    0
    2px
    9px
    rgba(25,43,60,.035);

}


.slot-topbar-left {

  min-width: 0;

  display: flex;

  align-items: center;

  gap: 12px;

}


.slot-menu-button {

  width: 44px;

  height: 44px;

  flex: 0 0 44px;

  display: flex;

  align-items: center;

  justify-content: center;

  border:
    1px solid
    #dce4ec;

  border-radius: 10px;

  background: #ffffff;

  color: #526b82;

  font-size: 18px;

  cursor: pointer;

}


.slot-menu-button:hover {

  background: #f3efff;

  border-color: #d3c6f5;

  color: #6046da;

}


/* =========================================================
   BREADCRUMB
   ========================================================= */

.slot-breadcrumb {

  min-width: 0;

}


.slot-breadcrumb-text {

  display: flex;

  flex-direction: column;

  gap: 4px;

}


.slot-breadcrumb-text span {

  color: #6346db;

  font-size: 9px;

  line-height: 1;

  font-weight: 950;

  letter-spacing: 1.7px;

}


.slot-breadcrumb-text strong {

  color: #142039;

  font-size: 17px;

  line-height: 1;

  font-weight: 950;

}


/* =========================================================
   TOPBAR RIGHT
   ========================================================= */

.slot-topbar-right {

  display: flex;

  align-items: center;

  gap: 9px;

  flex-shrink: 0;

}


.slot-top-action {

  position: relative;

  width: 42px;

  height: 42px;

  flex: 0 0 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  border:
    1px solid
    #dce4ed;

  border-radius: 10px;

  background: #ffffff;

  color: #536b81;

  font-size: 16px;

  cursor: pointer;

}


.slot-top-action:hover {

  background: #f4f0ff;

  border-color: #d3c7f5;

  color: #6246d8;

}


/* =========================================================
   BELL
   ========================================================= */

.notification-button {

  overflow: visible;

}


.notification-button
.fa-bell {

  color: #f1a000;

  font-size: 18px;

}


.slot-notification-dot {

  position: absolute;

  top: 7px;

  right: 7px;

  width: 8px;

  height: 8px;

  border:
    2px solid
    #ffffff;

  border-radius: 50%;

  background: #ef4444;

}


/* =========================================================
   TOP PROFILE
   ========================================================= */

.slot-top-profile {

  min-height: 44px;

  padding-left: 9px;

  display: flex;

  align-items: center;

  gap: 9px;

  border-left:
    1px solid
    #e4e8ee;

  text-decoration: none !important;

}


.slot-top-avatar {

  width: 42px;

  height: 42px;

  flex: 0 0 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  background:
    linear-gradient(
      135deg,
      #704cf4,
      #5742d4
    );

  color: #ffffff;

  font-size: 10px;

  font-weight: 950;

}


.slot-top-profile-text {

  display: flex;

  flex-direction: column;

}


.slot-top-profile-text strong {

  color: #17233b;

  font-size: 11px;

  font-weight: 950;

}


.slot-top-profile-text span {

  margin-top: 3px;

  color: #768399;

  font-size: 8px;

  font-weight: 800;

}


/* =========================================================
   PAGE CONTENT
   ========================================================= */

.slot-page-content {

  width: 100% !important;

  max-width: none !important;

  margin: 0 !important;

  padding:
    27px
    31px
    40px;

  background:
    radial-gradient(
      circle at 96% 13%,
      rgba(232,247,255,.42),
      transparent 25%
    ),
    radial-gradient(
      circle at 4% 53%,
      rgba(243,235,255,.42),
      transparent 27%
    ),
    #f3f6fb;

}


/* =========================================================
   PAGE HEADER
   ========================================================= */

.slot-page-header {

  width: 100%;

  min-height: 103px;

  margin-bottom: 19px;

  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 20px;

}


.slot-eyebrow {

  display: block;

  margin-bottom: 7px;

  color: #6548dc;

  font-size: 10px;

  line-height: 1;

  font-weight: 950;

  letter-spacing: 1.6px;

}


.slot-page-header h1 {

  margin:
    0
    0
    7px;

  color: #0c1831;

  font-size: 35px;

  line-height: 1.04;

  font-weight: 950;

  letter-spacing: -.5px;

}


.slot-page-header p {

  margin: 0;

  max-width: 900px;

  color: #5d6d83;

  font-size: 13px;

  line-height: 1.55;

  font-weight: 600;

}


.create-slot-button {

  height: 46px;

  padding:
    0
    18px;

  flex-shrink: 0;

  border: 0;

  border-radius: 10px;

  background:
    linear-gradient(
      135deg,
      #6044e3,
      #795df0
    );

  color: #ffffff;

  font-size: 10px;

  font-weight: 950;

  cursor: pointer;

  box-shadow:
    0
    7px
    16px
    rgba(91,66,218,.16);

}


.create-slot-button:hover {

  transform: translateY(-1px);

}


/* =========================================================
   BANNERS
   ========================================================= */

.action-banner {

  margin-bottom: 17px;

  padding:
    11px
    13px;

  display: flex;

  align-items: center;

  gap: 8px;

  border-radius: 9px;

  font-size: 9px;

  font-weight: 850;

}


.action-banner.success {

  background: #e9f9f1;

  color: #147c58;

  border:
    1px solid
    #bce6d3;

}


.action-banner.error {

  background: #fff0f2;

  color: #a62a3d;

  border:
    1px solid
    #f2c1c8;

}


.server-alert {

  margin-bottom: 17px;

  padding:
    11px
    13px;

  display: flex;

  align-items: center;

  gap: 8px;

  border-radius: 9px;

  background: #fff0f2;

  color: #a62a3d;

  border:
    1px solid
    #f2c1c8;

  font-size: 9px;

  font-weight: 850;

}


/* =========================================================
   KPI CARDS
   ========================================================= */

.slot-kpi-grid {

  width: 100%;

  display: grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0,1fr)
    );

  gap: 15px;

  margin-bottom: 20px;

}


.slot-kpi-card {

  min-height: 135px;

  padding: 18px;

  display: flex;

  align-items: center;

  gap: 14px;

  border-radius: 15px;

  box-shadow:
    0
    4px
    12px
    rgba(35,47,70,.035);

}


.slot-kpi-card.purple {

  background:
    linear-gradient(
      135deg,
      #f0e8ff,
      #e3d7ff
    );

  border:
    1px solid
    #d3c2fb;

}


.slot-kpi-card.orange {

  background:
    linear-gradient(
      135deg,
      #fff3e5,
      #ffe4c7
    );

  border:
    1px solid
    #f4d1aa;

}


.slot-kpi-card.blue {

  background:
    linear-gradient(
      135deg,
      #eaf7ff,
      #d9edff
    );

  border:
    1px solid
    #bddcf4;

}


.slot-kpi-card.green {

  background:
    linear-gradient(
      135deg,
      #eaf9f2,
      #d7f0e4
    );

  border:
    1px solid
    #bfe2d0;

}


.slot-kpi-icon {

  width: 51px;

  height: 51px;

  flex: 0 0 51px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 13px;

  background:
    rgba(255,255,255,.88);

  font-size: 20px;

}


.slot-kpi-card.purple
.slot-kpi-icon {

  color: #694ce2;

}


.slot-kpi-card.orange
.slot-kpi-icon {

  color: #d27b1f;

}


.slot-kpi-card.blue
.slot-kpi-icon {

  color: #287cc4;

}


.slot-kpi-card.green
.slot-kpi-icon {

  color: #159475;

}


.slot-kpi-card span {

  display: block;

  color: #627187;

  font-size: 8px;

  font-weight: 950;

  letter-spacing: 1px;

}


.slot-kpi-card strong {

  display: block;

  margin-top: 5px;

  color: #15233b;

  font-size: 28px;

  line-height: 1;

  font-weight: 950;

}


.slot-kpi-card small {

  display: block;

  margin-top: 6px;

  color: #617188;

  font-size: 9px;

  font-weight: 700;

}


/* =========================================================
   PANELS
   ========================================================= */

.slot-panel {

  width: 100%;

  margin-bottom: 18px;

  overflow: hidden;

  background:
    rgba(255,255,255,.97);

  border:
    1px solid
    #dce4ec;

  border-radius: 16px;

  box-shadow:
    0
    6px
    18px
    rgba(31,46,69,.045);

}


.slot-panel-header {

  min-height: 83px;

  padding:
    17px
    21px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 18px;

  border-bottom:
    1px solid
    #e7ecf1;

  background:
    linear-gradient(
      90deg,
      #ffffff,
      #fbfcff
    );

}


.slot-panel-header
span:first-child {

  color: #6547db;

  font-size: 8px;

  font-weight: 950;

  letter-spacing: 1.4px;

}


.slot-panel-header h2 {

  margin:
    5px
    0
    4px;

  color: #17233d;

  font-size: 20px;

  line-height: 1.15;

  font-weight: 950;

}


.slot-panel-header p {

  margin: 0;

  color: #778498;

  font-size: 9px;

  font-weight: 650;

}


.slot-panel-badge {

  min-width: 32px;

  height: 32px;

  padding:
    0
    9px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  font-size: 10px;

  font-weight: 950;

}


.slot-panel-badge.orange {

  background: #fff0d8;

  color: #b86a00;

}


.slot-panel-badge.blue {

  background: #e6f2ff;

  color: #286cbd;

}


.slot-panel-badge.purple {

  background: #eee8ff;

  color: #5f43d2;

}


/* =========================================================
   REQUESTS
   ========================================================= */

.slot-request-list {

  width: 100%;

}


.slot-request-card {

  min-height: 95px;

  padding:
    15px
    20px;

  display: grid;

  grid-template-columns:
    minmax(205px,1.35fr)
    minmax(110px,.72fr)
    minmax(115px,.78fr)
    minmax(185px,1fr)
    minmax(190px,1fr);

  align-items: center;

  gap: 15px;

  border-bottom:
    1px solid
    #edf1f5;

}


.request-student,
.scheduled-student,
.feedback-student {

  display: flex;

  align-items: center;

  gap: 10px;

}


.request-avatar,
.scheduled-avatar,
.feedback-avatar {

  width: 42px;

  height: 42px;

  flex: 0 0 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  background:
    linear-gradient(
      135deg,
      #6c4ce6,
      #5144d1
    );

  color: #ffffff;

  font-size: 10px;

  font-weight: 950;

}


.request-student strong,
.scheduled-student strong,
.feedback-student strong {

  display: block;

  color: #17233c;

  font-size: 11px;

  font-weight: 950;

}


.request-student span,
.scheduled-student span,
.feedback-student span {

  display: block;

  margin-top: 3px;

  color: #7c889a;

  font-size: 8px;

  font-weight: 750;

}


.request-detail span,
.feedback-detail span,
.scheduled-main span {

  display: block;

  color: #788499;

  font-size: 7px;

  font-weight: 950;

  letter-spacing: .8px;

}


.request-detail strong,
.feedback-detail strong,
.scheduled-main strong {

  display: block;

  margin-top: 5px;

  color: #1a263f;

  font-size: 10px;

  line-height: 1.35;

  font-weight: 950;

}


.request-status {

  display: flex;

  align-items: center;

  justify-content: flex-end;

  gap: 8px;

}


.request-pending-pill {

  padding:
    6px
    9px;

  border-radius: 18px;

  background: #fff2d9;

  color: #aa6400;

  font-size: 7px;

  font-weight: 950;

}


.accept-request-button {

  height: 34px;

  padding:
    0
    11px;

  border: 0;

  border-radius: 8px;

  background:
    linear-gradient(
      135deg,
      #6044e3,
      #795df0
    );

  color: #ffffff;

  font-size: 8px;

  font-weight: 950;

  cursor: pointer;

}


/* =========================================================
   AVAILABLE SLOTS
   ========================================================= */

.available-slot-grid {

  width: 100%;

  padding:
    19px;

  display: grid;

  grid-template-columns:
    repeat(
      3,
      minmax(235px,1fr)
    );

  gap: 14px;

}


.available-slot-card {

  min-height: 265px;

  padding: 17px;

  border:
    1px solid
    #d8e1eb;

  border-radius: 14px;

  background:
    linear-gradient(
      145deg,
      #ffffff,
      #f8f6ff
    );

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    border-color .18s ease;

}


.available-slot-card:hover {

  transform:
    translateY(-3px);

  border-color:
    #c8bbed;

  box-shadow:
    0
    10px
    24px
    rgba(65,47,158,.08);

}


.available-slot-top {

  display: flex;

  align-items: center;

  justify-content: space-between;

}


.available-slot-icon {

  width: 46px;

  height: 46px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  background: #e9e3ff;

  color: #5f43db;

  font-size: 19px;

}


.available-pill {

  padding:
    6px
    9px;

  border-radius: 20px;

  background: #ddf8ed;

  color: #14805c;

  font-size: 7px;

  font-weight: 950;

}


.available-slot-type {

  margin-top: 13px;

  color: #6245d6;

  font-size: 8px;

  font-weight: 950;

}


.available-slot-card h3 {

  margin:
    6px
    0;

  color: #15223d;

  font-size: 20px;

  font-weight: 950;

}


.available-slot-time {

  display: flex;

  align-items: center;

  gap: 7px;

  color: #36445d;

  font-size: 10px;

  font-weight: 850;

}


.available-slot-time i {

  color: #6245db;

}


.available-slot-skill {

  margin-top: 15px;

  padding:
    10px;

  border:
    1px solid
    #d5e5fb;

  border-radius: 9px;

  background: #eef5ff;

}


.available-slot-skill span,
.available-slot-id span {

  color: #78859b;

  font-size: 7px;

  font-weight: 950;

  letter-spacing: .8px;

}


.available-slot-skill strong,
.available-slot-id strong {

  display: block;

  margin-top: 4px;

  color: #214d87;

  font-size: 9px;

  font-weight: 950;

}


.available-slot-id {

  margin-top: 11px;

  padding-top: 10px;

  border-top:
    1px solid
    #e7ebf1;

}


.secondary-slot-button {

  height: 36px;

  padding:
    0
    12px;

  border:
    1px solid
    #d2c8fa;

  border-radius: 8px;

  background: #f5f1ff;

  color: #5941d2;

  font-size: 8px;

  font-weight: 950;

  cursor: pointer;

}


/* =========================================================
   SCHEDULED INTERVIEWS
   ========================================================= */

.scheduled-grid {

  width: 100%;

  padding:
    19px;

  display: grid;

  grid-template-columns:
    repeat(
      2,
      minmax(290px,1fr)
    );

  gap: 14px;

}


.scheduled-card {

  padding: 17px;

  border:
    1px solid
    #d8e1ed;

  border-radius: 14px;

  background:
    linear-gradient(
      145deg,
      #ffffff,
      #f7f9ff
    );

  cursor: pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    border-color .18s ease;

}


.scheduled-card:hover {

  transform:
    translateY(-3px);

  border-color:
    #c9bdf2;

  box-shadow:
    0
    10px
    23px
    rgba(65,47,158,.09);

}


.scheduled-card-top {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

}


.scheduled-status {

  padding:
    6px
    9px;

  border-radius: 18px;

  background: #e4f8ed;

  color: #148159;

  font-size: 7px;

  font-weight: 950;

}


.scheduled-main {

  margin-top: 15px;

  display: grid;

  grid-template-columns:
    1fr
    1fr;

  gap: 9px;

}


.scheduled-main > div {

  padding:
    9px;

  border:
    1px solid
    #e3e8ef;

  border-radius: 8px;

  background: #f8fafc;

}


.scheduled-card-footer {

  margin-top: 12px;

  padding-top: 10px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  border-top:
    1px solid
    #e7ebf1;

  color: #67748a;

  font-size: 8px;

  font-weight: 800;

}


.scheduled-card-footer i {

  color: #5f45da;

}


.scheduled-card-footer strong {

  color: #5c43d4;

  font-size: 8px;

}


/* =========================================================
   FEEDBACK PENDING
   ========================================================= */

.feedback-pending-card {

  min-height: 87px;

  padding:
    14px
    20px;

  display: grid;

  grid-template-columns:
    minmax(205px,1.4fr)
    .8fr
    .8fr
    .8fr
    auto;

  align-items: center;

  gap: 15px;

  border-bottom:
    1px solid
    #edf1f5;

}


.give-feedback-button {

  height: 34px;

  padding:
    0
    11px;

  border: 0;

  border-radius: 8px;

  background:
    linear-gradient(
      135deg,
      #6044e3,
      #795df0
    );

  color: #ffffff;

  font-size: 8px;

  font-weight: 950;

  cursor: pointer;

}


/* =========================================================
   EMPTY STATES
   ========================================================= */

.slot-empty-state {

  padding:
    42px
    18px;

  text-align: center;

}


.empty-state-icon {

  width: 48px;

  height: 48px;

  margin:
    0
    auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 13px;

  font-size: 20px;

}


.empty-state-icon.green {

  background: #def8eb;

  color: #14825b;

}


.empty-state-icon.purple {

  background: #eee8ff;

  color: #6045da;

}


.empty-state-icon.blue {

  background: #e6f2ff;

  color: #286fbe;

}


.slot-empty-state h3 {

  margin:
    10px
    0
    4px;

  color: #29344b;

  font-size: 15px;

  font-weight: 950;

}


.slot-empty-state p {

  margin: 0;

  color: #788397;

  font-size: 9px;

}


/* =========================================================
   MODALS
   ========================================================= */

.slot-modal-backdrop {

  position: fixed !important;

  inset: 0 !important;

  z-index: 9000 !important;

  padding: 24px;

  display: flex;

  align-items: center;

  justify-content: center;

  background:
    rgba(18,25,43,.55);

}


.slot-modal {

  width:
    min(760px,95vw);

  max-height: 91vh;

  display: flex;

  flex-direction: column;

  overflow: hidden;

  border:
    1px solid
    #ded8ed;

  border-radius: 17px;

  background: #ffffff;

  box-shadow:
    0
    28px
    65px
    rgba(20,25,50,.25);

}


.interview-details-modal {

  width:
    min(880px,95vw);

}


.slot-modal-header {

  min-height: 82px;

  padding:
    18px
    21px;

  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 15px;

  background:
    linear-gradient(
      135deg,
      #ffffff,
      #faf8ff
    );

  border-bottom:
    1px solid
    #e7ebf1;

}


.slot-modal-header span {

  color: #6245da;

  font-size: 8px;

  font-weight: 950;

  letter-spacing: 1.3px;

}


.slot-modal-header h2 {

  margin:
    4px
    0
    4px;

  color: #17223b;

  font-size: 21px;

  font-weight: 950;

}


.slot-modal-header p {

  margin: 0;

  color: #758197;

  font-size: 9px;

}


.slot-modal-close {

  width: 35px;

  height: 35px;

  border:
    1px solid
    #dce2ea;

  border-radius: 8px;

  background: #ffffff;

  color: #657289;

  cursor: pointer;

}


.slot-modal-body {

  flex: 1;

  min-height: 0;

  overflow-y: auto;

  padding:
    20px
    21px;

}


.slot-modal-footer {

  min-height: 65px;

  padding:
    12px
    21px;

  display: flex;

  align-items: center;

  justify-content: flex-end;

  gap: 8px;

  border-top:
    1px solid
    #e8ecf1;

  background: #fafbfd;

}


/* =========================================================
   FORM
   ========================================================= */

.slot-form-row {

  display: grid;

  grid-template-columns:
    1fr
    1fr;

  gap: 12px;

}


.slot-form-group {

  margin-bottom: 14px;

}


.slot-form-group label,
.feedback-form-group label,
.score-input-box label,
.token-box label {

  display: block;

  margin-bottom: 6px;

  color: #647087;

  font-size: 8px;

  font-weight: 950;

  letter-spacing: .8px;

}


.slot-form-group input,
.slot-form-group select,
.token-box input,
.score-input-box input,
.feedback-form-group textarea {

  width: 100%;

  border:
    1px solid
    #d8e0e9;

  border-radius: 8px;

  background: #ffffff;

  color: #27344d;

  font-family: inherit;

  font-size: 10px;

  outline: none;

}


.slot-form-group input,
.slot-form-group select,
.token-box input,
.score-input-box input {

  height: 38px;

  padding:
    0
    9px;

}


.feedback-form-group textarea {

  min-height: 88px;

  padding: 10px;

  resize: vertical;

  line-height: 1.5;

}


.slot-form-group input:focus,
.slot-form-group select:focus,
.token-box input:focus,
.score-input-box input:focus,
.feedback-form-group textarea:focus {

  border-color: #9078e9;

  box-shadow:
    0
    0
    0
    3px
    rgba(112,80,220,.08);

}


.slot-info-box {

  padding:
    11px;

  display: flex;

  align-items: flex-start;

  gap: 8px;

  border:
    1px solid
    #d6ccf7;

  border-radius: 9px;

  background: #f7f3ff;

  color: #62567d;

  font-size: 8px;

  line-height: 1.5;

}


.slot-form-error {

  margin-top: 11px;

  padding:
    9px
    11px;

  display: flex;

  align-items: center;

  gap: 7px;

  border:
    1px solid
    #fecdd3;

  border-radius: 8px;

  background: #fff0f2;

  color: #ad283d;

  font-size: 8px;

  font-weight: 850;

}


/* =========================================================
   MODAL BUTTONS
   ========================================================= */

.modal-cancel,
.modal-create,
.modal-verify,
.modal-complete {

  height: 37px;

  padding:
    0
    12px;

  border-radius: 8px;

  font-family: inherit;

  font-size: 8px;

  font-weight: 950;

  cursor: pointer;

}


.modal-cancel {

  border:
    1px solid
    #d8e0e8;

  background: #ffffff;

  color: #667389;

}


.modal-create,
.modal-verify,
.modal-complete {

  border: 0;

  background:
    linear-gradient(
      135deg,
      #6245dd,
      #7e61ea
    );

  color: #ffffff;

}


/* =========================================================
   INTERVIEW DETAILS
   ========================================================= */

.interview-detail-top {

  margin-bottom: 16px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

}


.detail-student-large {

  display: flex;

  align-items: center;

  gap: 11px;

}


.detail-student-avatar {

  width: 50px;

  height: 50px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  background:
    linear-gradient(
      135deg,
      #6948e3,
      #5143ce
    );

  color: #ffffff;

  font-size: 10px;

  font-weight: 950;

}


.detail-student-large strong {

  display: block;

  color: #17233c;

  font-size: 13px;

  font-weight: 950;

}


.detail-student-large span {

  display: block;

  margin-top: 3px;

  color: #7a8799;

  font-size: 8px;

}


.interview-detail-grid {

  display: grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0,1fr)
    );

  gap: 9px;

}


.interview-detail-grid > div {

  padding:
    10px;

  border:
    1px solid
    #dfe5ec;

  border-radius: 8px;

  background: #fafbfd;

}


.interview-detail-grid span {

  display: block;

  color: #788498;

  font-size: 7px;

  font-weight: 950;

  letter-spacing: .7px;

}


.interview-detail-grid strong {

  display: block;

  margin-top: 5px;

  color: #1d2941;

  font-size: 9px;

  line-height: 1.3;

  font-weight: 950;

}


/* =========================================================
   STATUS EDITOR
   ========================================================= */

.slot-status-editor {

  margin-top: 16px;

  padding:
    14px;

  border:
    1px solid
    #ddd7f4;

  border-radius: 11px;

  background:
    linear-gradient(
      135deg,
      #faf9ff,
      #f5f7ff
    );

}


.slot-status-editor-head {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;

}


.slot-status-editor-head
> div
> span {

  display: block;

  color: #6751d7;

  font-size: 8px;

  font-weight: 950;

  letter-spacing: 1px;

}


.slot-status-editor-head strong {

  display: block;

  margin-top: 4px;

  color: #18243d;

  font-size: 9px;

  font-weight: 900;

}


.slot-status-current {

  padding:
    6px
    9px;

  border-radius: 17px;

  background: #e6efff;

  color: #2c60ca;

  font-size: 8px;

  font-weight: 950;

}


.slot-status-editor-row {

  margin-top: 11px;

}


.slot-status-select {

  width: 100%;

}


.slot-status-select label {

  display: block;

  margin-bottom: 6px;

  color: #6d7a90;

  font-size: 8px;

  font-weight: 950;

  letter-spacing: .7px;

}


.slot-status-select select {

  width: 100%;

  height: 38px;

  padding:
    0
    9px;

  border:
    1px solid
    #d7deea;

  border-radius: 8px;

  background: #ffffff;

  color: #17233e;

  font-family: inherit;

  font-size: 10px;

  font-weight: 900;

}


/* =========================================================
   QR
   ========================================================= */

.verify-student-card {

  margin-bottom: 15px;

  padding:
    11px;

  display: flex;

  align-items: center;

  gap: 10px;

  border:
    1px solid
    #dedff0;

  border-radius: 10px;

  background: #faf9ff;

}


.verify-avatar {

  width: 42px;

  height: 42px;

  flex: 0 0 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 10px;

  background:
    linear-gradient(
      135deg,
      #704cf4,
      #5646d5
    );

  color: #ffffff;

  font-size: 9px;

  font-weight: 950;

}


.verify-student-card strong,
.feedback-form-student strong {

  display: block;

  color: #202b44;

  font-size: 10px;

  font-weight: 950;

}


.verify-student-card span,
.feedback-form-student span {

  display: block;

  margin-top: 3px;

  color: #758095;

  font-size: 8px;

}


.verify-session-grid {

  display: grid;

  grid-template-columns:
    repeat(3,1fr);

  gap: 9px;

  margin-bottom: 15px;

}


.verify-session-grid > div {

  padding:
    10px;

  border:
    1px solid
    #dde4ec;

  border-radius: 8px;

  background: #fafbfd;

}


.verify-session-grid span {

  color: #778298;

  font-size: 7px;

  font-weight: 950;

}


.verify-session-grid strong {

  display: block;

  margin-top: 5px;

  color: #202c45;

  font-size: 9px;

}


.token-box {

  padding:
    12px;

  border:
    1px solid
    #d8dff0;

  border-radius: 9px;

  background: #faf9ff;

}


/* =========================================================
   FEEDBACK
   ========================================================= */

.feedback-form-student {

  margin-bottom: 15px;

  padding:
    11px;

  display: flex;

  align-items: center;

  gap: 10px;

  border:
    1px solid
    #dedff0;

  border-radius: 10px;

  background: #faf9ff;

}


.feedback-score-grid {

  display: grid;

  grid-template-columns:
    repeat(4,1fr);

  gap: 9px;

  margin-bottom: 15px;

}


.score-input-box,
.overall-score-box {

  padding:
    10px;

  border:
    1px solid
    #dce3eb;

  border-radius: 9px;

  background: #fafbfd;

}


.overall-score-box {

  background:
    linear-gradient(
      135deg,
      #eee8ff,
      #e3dbff
    );

  border-color:
    #cec2fa;

}


.overall-score-box span {

  display: block;

  color: #6349d4;

  font-size: 7px;

  font-weight: 950;

}


.overall-score-box strong {

  display: block;

  margin-top: 6px;

  color: #3d289f;

  font-size: 25px;

  font-weight: 950;

}


/* =========================================================
   FOOTER
   ========================================================= */

.slot-page-footer {

  padding:
    1px
    2px
    8px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  color: #7c8799;

  font-size: 8px;

  font-weight: 700;

}


/* =========================================================
   DESKTOP LARGE SCREEN
   ========================================================= */

@media (min-width: 1500px) {

  .slot-page-content {

    padding-left: 34px;

    padding-right: 34px;

  }

}


/* =========================================================
   MEDIUM DESKTOP
   ========================================================= */

@media (max-width: 1250px) {

  .slot-kpi-grid {

    grid-template-columns:
      repeat(
        2,
        minmax(0,1fr)
      );

  }


  .available-slot-grid {

    grid-template-columns:
      repeat(
        2,
        minmax(220px,1fr)
      );

  }


  .scheduled-grid {

    grid-template-columns:
      1fr;

  }


  .slot-request-card {

    grid-template-columns:
      minmax(190px,1fr)
      minmax(105px,.7fr)
      minmax(110px,.75fr)
      minmax(170px,1fr);

  }


  .request-status {

    grid-column:
      1/-1;

    justify-content: flex-start;

  }


  .feedback-pending-card {

    grid-template-columns:
      1.3fr
      .8fr
      .8fr
      .8fr;

  }


  .feedback-pending-card
  .give-feedback-button {

    grid-column:
      1/-1;

    justify-self: start;

  }


  .interview-detail-grid {

    grid-template-columns:
      repeat(3,1fr);

  }

}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

  .campus360-slot-sidebar {

    position: fixed !important;

    left: 0 !important;

    top: 0 !important;

    bottom: 0 !important;

    transform:
      translateX(-100%);

    width: 264px !important;

    min-width: 264px !important;

    max-width: 264px !important;

    background:
      linear-gradient(
        180deg,
        #130d2f 0%,
        #160d38 48%,
        #100a29 100%
      ) !important;

    border-right:
      1px solid
      #2d2157 !important;

    box-shadow:
      10px
      0
      30px
      rgba(32,24,65,.30);

    transition:
      transform .25s ease;

  }


  .campus360-slot-app:not(.sidebar-collapsed)
  .campus360-slot-sidebar {

    transform:
      translateX(0);

  }


  .campus360-slot-main,
  .campus360-slot-app.sidebar-collapsed
  .campus360-slot-main {

    width: 100% !important;

    max-width: 100% !important;

  }


  .slot-page-header {

    align-items: flex-start;

    flex-direction: column;

  }


  .create-slot-button {

    align-self: flex-start;

  }


  .slot-request-card {

    grid-template-columns:
      1fr
      1fr;

  }


  .request-status {

    grid-column:
      1/-1;

    justify-content: flex-start;

  }


  .interview-detail-grid {

    grid-template-columns:
      repeat(2,1fr);

  }


  .feedback-score-grid {

    grid-template-columns:
      repeat(2,1fr);

  }

}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 700px) {

  .slot-topbar {

    height: 64px;

    min-height: 64px;

    padding:
      0
      10px;

  }


  .slot-menu-button,
  .slot-top-action {

    width: 38px;

    height: 38px;

    flex-basis: 38px;

  }


  .slot-top-profile-text {

    display: none;

  }


  .slot-top-profile {

    padding-left: 5px;

  }


  .slot-page-content {

    padding:
      18px
      12px
      30px;

  }


  .slot-page-header h1 {

    font-size: 28px;

  }


  .slot-kpi-grid {

    grid-template-columns:
      1fr;

  }


  .available-slot-grid,
  .scheduled-grid {

    grid-template-columns:
      1fr;

  }


  .slot-request-card {

    grid-template-columns:
      1fr;

  }


  .request-status {

    grid-column: auto;

  }


  .feedback-pending-card {

    grid-template-columns:
      1fr;

  }


  .give-feedback-button {

    justify-self: start;

  }


  .interview-detail-grid {

    grid-template-columns:
      1fr;

  }


  .verify-session-grid {

    grid-template-columns:
      1fr;

  }


  .feedback-score-grid {

    grid-template-columns:
      1fr;

  }


  .slot-form-row {

    grid-template-columns:
      1fr;

  }


  .interview-detail-top {

    align-items: flex-start;

    flex-direction: column;

  }

}


/* =========================================================
   FINAL SIDEBAR COLOR OVERRIDE
   ========================================================= */

.campus360-slot-app
.campus360-slot-sidebar {

  background:
    linear-gradient(
      180deg,
      #130d2f 0%,
      #160d38 48%,
      #100a29 100%
    ) !important;

  border-right:
    1px solid
    #2d2157 !important;

}


.campus360-slot-app
.slot-brand {

  background:
    linear-gradient(
      135deg,
      #170e38,
      #1c1045
    ) !important;

  border-bottom:
    1px solid
    #2d2157 !important;

}


.campus360-slot-app
.slot-trainer-profile {

  background:
    linear-gradient(
      135deg,
      #211342,
      #29164f
    ) !important;

  border-color:
    #4b3475 !important;

}


.campus360-slot-app
.slot-nav-item {

  background:
    transparent !important;

  color:
    #c4b8dc !important;

}


.campus360-slot-app
.slot-nav-item:hover {

  background:
    rgba(124,58,237,.18) !important;

  color:
    #ffffff !important;

}


.campus360-slot-app
.slot-nav-item.active {

  background:
    linear-gradient(
      90deg,
      #7c3aed 0%,
      #8b3ff2 100%
    ) !important;

  color:
    #ffffff !important;

  border-left:
    4px solid
    #a78bfa !important;

}


.campus360-slot-app
.slot-nav-icon {

  color:
    #a99ac8 !important;

}


.campus360-slot-app
.slot-nav-item:hover
.slot-nav-icon,

.campus360-slot-app
.slot-nav-item.active
.slot-nav-icon {

  color:
    #ffffff !important;

}


.campus360-slot-app
.slot-brand-text strong,

.campus360-slot-app
.slot-trainer-info strong {

  color:
    #ffffff !important;

}


.campus360-slot-app
.slot-brand-text span,

.campus360-slot-app
.slot-trainer-info span {

  color:
    #b9abd8 !important;

}


.campus360-slot-app
.slot-nav-label {

  color:
    #9283b6 !important;

}


.campus360-slot-app
.slot-nav-count {

  background:
    #3a2764 !important;

  color:
    #d9ceef !important;

}


.campus360-slot-app
.slot-nav-item.active
.slot-nav-count {

  background:
    rgba(255,255,255,.18) !important;

  color:
    #ffffff !important;

}


/* =========================================================
   END
   ========================================================= */

sp_widget.script:
(function() {

  /* =========================================================
     TABLES
     ========================================================= */

  var AVAILABILITY_TABLE =
    'x_snc_campus360_trainer_interview_availability';

  var SLOT_REQUEST_TABLE =
    'x_snc_campus360_mock_interview_slot_request';

  var REQUEST_TRAINER_TABLE =
    'x_snc_campus360_mock_interview_request_trainer';

  var MOCK_INTERVIEW_TABLE =
    'x_snc_campus360_mock_interview';

  var FEEDBACK_TABLE =
    'x_snc_campus360_interview_feedback';

  var TRAINER_TABLE =
    'x_snc_campus360_trainer_master';

  var STUDENT_TABLE =
    'x_snc_campus360_student_master';


  /* =========================================================
     INITIAL DATA
     ========================================================= */

  data.error = '';

  data.trainer = {
    sys_id: '',
    id: '',
    name: 'Trainer',
    initials: 'TR'
  };

  data.metrics = {
    availableSlots: 0,
    pendingRequests: 0,
    scheduled: 0,
    feedbackPending: 0,
    verified: 0
  };

  data.availableSlots = [];
  data.requests = [];
  data.scheduledInterviews = [];
  data.feedbackPending = [];


  /* =========================================================
     STATUS OPTIONS
     ========================================================= */

  data.interviewStatusOptions = [

    {
      value: 'Scheduled',
      label: 'Scheduled'
    },

    {
      value: 'Completed',
      label: 'Completed'
    }

  ];


  /* =========================================================
     CURRENT TRAINER
     ========================================================= */

  var trainerParam =
    clean(
      $sp.getParameter(
        'trainer'
      )
    );


  var trainerGR =
    new GlideRecord(
      TRAINER_TABLE
    );


  var trainerIdField =
    resolveField(
      trainerGR,
      ['trainer_id'],
      ['Trainer ID']
    );


  if (
    trainerParam &&
    trainerIdField
  ) {

    trainerGR.addQuery(
      trainerIdField,
      trainerParam
    );

  }


  trainerGR.setLimit(1);
  trainerGR.query();


  if (
    !trainerGR.next()
  ) {

    data.error =
      'Trainer record could not be found.';

    return;

  }


  var trainerSysId =
    trainerGR.getUniqueValue();


  data.trainer = {

    sys_id:
      trainerSysId,

    id:
      getSafe(
        trainerGR,
        ['trainer_id'],
        ['Trainer ID']
      ),

    name:
      getSafe(
        trainerGR,
        ['trainer_name'],
        ['Trainer Name']
      ) ||
      trainerGR.getDisplayValue(),

    initials:
      getInitials(
        getSafe(
          trainerGR,
          ['trainer_name'],
          ['Trainer Name']
        ) ||
        trainerGR.getDisplayValue()
      )

  };


  /* =========================================================
     ACTIONS
     ========================================================= */

  if (
    input &&
    input.action
  ) {

    if (
      input.action ==
      'create_slot'
    ) {

      createSlot();

    }


    else if (
      input.action ==
      'accept_request'
    ) {

      acceptRequest();

    }


    else if (
      input.action ==
      'verify_qr'
    ) {

      verifyQR();

    }


    else if (
      input.action ==
      'mark_completed'
    ) {

      markCompleted();

    }


    else if (
      input.action ==
      'submit_feedback'
    ) {

      submitFeedback();

    }

  }


  /* =========================================================
     LOAD PAGE DATA
     ========================================================= */

  loadPage();


  function loadPage() {

    data.availableSlots = [];
    data.requests = [];
    data.scheduledInterviews = [];
    data.feedbackPending = [];


    loadAvailableSlots();
    loadRequests();
    loadScheduledInterviews();
    loadFeedbackPending();


    data.metrics.availableSlots =
      data.availableSlots.length;


    data.metrics.pendingRequests =
      data.requests.length;


    data.metrics.scheduled =
      data.scheduledInterviews.length;


    data.metrics.feedbackPending =
      data.feedbackPending.length;


    data.metrics.verified =
      countVerified();

  }


  /* =========================================================
     AVAILABLE SLOTS
     ========================================================= */

  function loadAvailableSlots() {

    var gr =
      new GlideRecord(
        AVAILABILITY_TABLE
      );


    var trainerField =
      resolveField(
        gr,
        [
          'trainer',
          'trainer_reference'
        ],
        ['Trainer']
      );


    var statusField =
      resolveField(
        gr,
        ['status'],
        ['Status']
      );


    if (
      !trainerField
    ) {

      return;

    }


    gr.addQuery(
      trainerField,
      trainerSysId
    );


    if (
      statusField
    ) {

      gr.addQuery(
        statusField,
        'Available'
      );

    }


    gr.orderBy(
      'available_date'
    );

    gr.query();


    while (
      gr.next()
    ) {

      data.availableSlots.push(
        makeAvailabilityObject(
          gr
        )
      );

    }

  }


  /* =========================================================
     STUDENT REQUESTS
     ========================================================= */

  function loadRequests() {

    var availabilityIds =
      getTrainerAvailabilityIds();


    if (
      !availabilityIds.length
    ) {

      return;

    }


    var gr =
      new GlideRecord(
        SLOT_REQUEST_TABLE
      );


    var availabilityField =
      resolveField(
        gr,
        ['selected_availability'],
        ['Selected Availability']
      );


    var statusField =
      resolveField(
        gr,
        ['status'],
        ['Status']
      );


    if (
      !availabilityField
    ) {

      return;

    }


    gr.addQuery(
      availabilityField,
      'IN',
      availabilityIds.join(',')
    );


    if (
      statusField
    ) {

      gr.addQuery(
        statusField,
        'Requested'
      );

    }


    gr.orderByDesc(
      'sys_created_on'
    );

    gr.query();


    while (
      gr.next()
    ) {

      data.requests.push(
        makeRequestObject(
          gr
        )
      );

    }

  }


  /* =========================================================
     SCHEDULED INTERVIEWS
     ========================================================= */

  function loadScheduledInterviews() {

    var gr =
      new GlideRecord(
        MOCK_INTERVIEW_TABLE
      );


    var trainerField =
      resolveField(
        gr,
        [
          'trainer_reference',
          'trainer'
        ],
        [
          'Trainer Reference',
          'Trainer'
        ]
      );


    var statusField =
      resolveField(
        gr,
        ['interview_status'],
        ['Interview Status']
      );


    if (
      !trainerField ||
      !statusField
    ) {

      return;

    }


    gr.addQuery(
      trainerField,
      trainerSysId
    );


    gr.addQuery(
      statusField,
      'Scheduled'
    );


    gr.orderBy(
      'interview_date'
    );

    gr.query();


    while (
      gr.next()
    ) {

      data.scheduledInterviews.push(
        makeMockObject(
          gr
        )
      );

    }

  }


  /* =========================================================
     FEEDBACK PENDING
     ========================================================= */

  function loadFeedbackPending() {

    var gr =
      new GlideRecord(
        MOCK_INTERVIEW_TABLE
      );


    var trainerField =
      resolveField(
        gr,
        [
          'trainer_reference',
          'trainer'
        ],
        [
          'Trainer Reference',
          'Trainer'
        ]
      );


    var statusField =
      resolveField(
        gr,
        ['interview_status'],
        ['Interview Status']
      );


    if (
      !trainerField ||
      !statusField
    ) {

      return;

    }


    gr.addQuery(
      trainerField,
      trainerSysId
    );


    gr.addQuery(
      statusField,
      'Completed'
    );


    gr.query();


    while (
      gr.next()
    ) {

      data.feedbackPending.push(
        makeMockObject(
          gr
        )
      );

    }

  }


  /* =========================================================
     CREATE SLOT
     ========================================================= */

  function createSlot() {

    data.slotSuccess =
      false;

    data.slotMessage =
      '';


    var interviewType =
      clean(
        input.interviewType
      );


    var skillArea =
      clean(
        input.skillArea
      );


    var availableDate =
      normalizeDate(
        input.availableDate
      );


    var startTime =
      normalizeTime(
        input.startTime
      );


    var endTime =
      normalizeTime(
        input.endTime
      );


    if (!interviewType) {

      data.slotMessage =
        'Interview Type is required.';

      return;

    }


    if (!availableDate) {

      data.slotMessage =
        'Available Date is required.';

      return;

    }


    if (!startTime || !endTime) {

      data.slotMessage =
        'Start Time and End Time are required.';

      return;

    }


    if (
      timeToMinutes(endTime) <=
      timeToMinutes(startTime)
    ) {

      data.slotMessage =
        'End Time must be after Start Time.';

      return;

    }


    var gr =
      new GlideRecord(
        AVAILABILITY_TABLE
      );


    if (
      !gr.isValid()
    ) {

      data.slotMessage =
        'Trainer Interview Availability table could not be accessed.';

      return;

    }


    var trainerField =
      resolveField(
        gr,
        [
          'trainer',
          'trainer_reference'
        ],
        ['Trainer']
      );


    var idField =
      resolveField(
        gr,
        ['availability_id'],
        ['Availability ID']
      );


    var dateField =
      resolveField(
        gr,
        ['available_date'],
        ['Available Date']
      );


    var startField =
      resolveField(
        gr,
        ['start_time'],
        ['Start Time']
      );


    var endField =
      resolveField(
        gr,
        ['end_time'],
        ['End Time']
      );


    var typeField =
      resolveField(
        gr,
        ['interview_type'],
        ['Interview Type']
      );


    var skillField =
      resolveField(
        gr,
        ['skill_area'],
        ['Skill Area']
      );


    var statusField =
      resolveField(
        gr,
        ['status'],
        ['Status']
      );


    if (
      !trainerField ||
      !idField ||
      !dateField ||
      !startField ||
      !endField ||
      !typeField ||
      !statusField
    ) {

      data.slotMessage =
        'Required availability fields are missing.';

      return;

    }


    gr.initialize();


    gr.setValue(
      idField,
      generateAvailabilityId()
    );


    gr.setValue(
      trainerField,
      trainerSysId
    );


    gr.setValue(
      dateField,
      availableDate
    );


    gr.setValue(
      startField,
      startTime
    );


    gr.setValue(
      endField,
      endTime
    );


    gr.setValue(
      typeField,
      interviewType
    );


    if (
      skillField
    ) {

      gr.setValue(
        skillField,
        skillArea
      );

    }


    gr.setValue(
      statusField,
      'Available'
    );


    if (
      gr.isValidField(
        'active'
      )
    ) {

      gr.setValue(
        'active',
        true
      );

    }


    var sysId =
      gr.insert();


    if (!sysId) {

      data.slotMessage =
        'Available slot could not be created.';

      return;

    }


    data.slotSuccess =
      true;

    data.slotMessage =
      'Interview slot created successfully.';

  }


  /* =========================================================
     ACCEPT STUDENT REQUEST
     ========================================================= */

  function acceptRequest() {

    data.acceptSuccess =
      false;

    data.acceptMessage =
      '';


    var requestSysId =
      clean(
        input.request
      );


    if (!requestSysId) {

      data.acceptMessage =
        'Student request is missing.';

      return;

    }


    var requestGR =
      new GlideRecord(
        SLOT_REQUEST_TABLE
      );


    if (
      !requestGR.get(
        requestSysId
      )
    ) {

      data.acceptMessage =
        'Student request could not be found.';

      return;

    }


    var requestStatusField =
      resolveField(
        requestGR,
        ['status'],
        ['Status']
      );


    var studentField =
      resolveField(
        requestGR,
        ['student_reference'],
        ['Student']
      );


    var availabilityField =
      resolveField(
        requestGR,
        ['selected_availability'],
        ['Selected Availability']
      );


    if (
      !requestStatusField ||
      !studentField ||
      !availabilityField
    ) {

      data.acceptMessage =
        'Required request fields are missing.';

      return;

    }


    if (
      requestGR.getValue(
        requestStatusField
      ) != 'Requested'
    ) {

      data.acceptMessage =
        'This request has already been processed.';

      return;

    }


    var availabilitySysId =
      requestGR.getValue(
        availabilityField
      );


    var availabilityGR =
      new GlideRecord(
        AVAILABILITY_TABLE
      );


    if (
      !availabilityGR.get(
        availabilitySysId
      )
    ) {

      data.acceptMessage =
        'Interview availability could not be found.';

      return;

    }


    var availabilityTrainerField =
      resolveField(
        availabilityGR,
        [
          'trainer',
          'trainer_reference'
        ],
        ['Trainer']
      );


    var availabilityStatusField =
      resolveField(
        availabilityGR,
        ['status'],
        ['Status']
      );


    if (
      !availabilityTrainerField ||
      !availabilityStatusField
    ) {

      data.acceptMessage =
        'Availability configuration is incomplete.';

      return;

    }


    if (
      availabilityGR.getValue(
        availabilityTrainerField
      ) != trainerSysId
    ) {

      data.acceptMessage =
        'This slot does not belong to the current trainer.';

      return;

    }


    if (
      availabilityGR.getValue(
        availabilityStatusField
      ) != 'Available'
    ) {

      data.acceptMessage =
        'This slot is no longer available.';

      return;

    }


    /* -----------------------------------------------------
       CREATE MOCK INTERVIEW
       Only after trainer accepts.
       ----------------------------------------------------- */

    var mockGR =
      new GlideRecord(
        MOCK_INTERVIEW_TABLE
      );


    mockGR.initialize();


    var mockInterviewIdField =
      resolveField(
        mockGR,
        ['interview_id'],
        ['Interview ID']
      );


    var mockStudentField =
      resolveField(
        mockGR,
        [
          'student_reference',
          'student'
        ],
        [
          'Student Reference',
          'Student'
        ]
      );


    var mockTrainerField =
      resolveField(
        mockGR,
        [
          'trainer_reference',
          'trainer'
        ],
        [
          'Trainer Reference',
          'Trainer'
        ]
      );


    var mockTypeField =
      resolveField(
        mockGR,
        ['interview_type'],
        ['Interview Type']
      );


    var mockDateField =
      resolveField(
        mockGR,
        ['interview_date'],
        ['Interview Date']
      );


    var mockStartField =
      resolveField(
        mockGR,
        ['start_time'],
        ['Start Time']
      );


    var mockEndField =
      resolveField(
        mockGR,
        ['end_time'],
        ['End Time']
      );


    var mockSlotRequestField =
      resolveField(
        mockGR,
        ['slot_request'],
        ['Slot Request']
      );


    var mockQRField =
      resolveField(
        mockGR,
        ['qr_code'],
        ['QR Code']
      );


    var mockQRStatusField =
      resolveField(
        mockGR,
        ['qr_status'],
        ['QR Status']
      );


    var mockAttendanceField =
      resolveField(
        mockGR,
        ['attendance_status'],
        ['Attendance Status']
      );


    var mockInterviewStatusField =
      resolveField(
        mockGR,
        ['interview_status'],
        ['Interview Status']
      );


    if (
      !mockInterviewIdField ||
      !mockStudentField ||
      !mockTrainerField ||
      !mockTypeField ||
      !mockDateField ||
      !mockStartField ||
      !mockEndField ||
      !mockQRField ||
      !mockQRStatusField ||
      !mockAttendanceField ||
      !mockInterviewStatusField
    ) {

      data.acceptMessage =
        'Required Mock Interview fields are missing.';

      return;

    }


    mockGR.setValue(
      mockInterviewIdField,
      generateInterviewId()
    );


    mockGR.setValue(
      mockStudentField,
      requestGR.getValue(
        studentField
      )
    );


    mockGR.setValue(
      mockTrainerField,
      trainerSysId
    );


    mockGR.setValue(
      mockTypeField,
      getSafe(
        availabilityGR,
        ['interview_type'],
        ['Interview Type']
      )
    );


    mockGR.setValue(
      mockDateField,
      getSafe(
        availabilityGR,
        ['available_date'],
        ['Available Date']
      )
    );


    mockGR.setValue(
      mockStartField,
      getSafe(
        availabilityGR,
        ['start_time'],
        ['Start Time']
      )
    );


    mockGR.setValue(
      mockEndField,
      getSafe(
        availabilityGR,
        ['end_time'],
        ['End Time']
      )
    );


    if (
      mockSlotRequestField
    ) {

      mockGR.setValue(
        mockSlotRequestField,
        requestSysId
      );

    }


    var qrToken =
      generateQRToken();


    var qrUrl =
      'https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=' +
      encodeURIComponent(
        qrToken
      );


    mockGR.setValue(
      mockQRField,
      qrUrl
    );


    mockGR.setValue(
      mockQRStatusField,
      'Generated'
    );


    mockGR.setValue(
      mockAttendanceField,
      'Scheduled'
    );


    mockGR.setValue(
      mockInterviewStatusField,
      'Scheduled'
    );


    var mockSysId =
      mockGR.insert();


    if (!mockSysId) {

      data.acceptMessage =
        'Mock Interview could not be created.';

      return;

    }


    requestGR.setValue(
      requestStatusField,
      'Accepted'
    );


    if (
      requestGR.isValidField(
        'accepted_trainer'
      )
    ) {

      requestGR.setValue(
        'accepted_trainer',
        trainerSysId
      );

    }


    if (
      requestGR.isValidField(
        'mock_interview'
      )
    ) {

      requestGR.setValue(
        'mock_interview',
        mockSysId
      );

    }


    if (
      requestGR.isValidField(
        'accepted_on'
      )
    ) {

      requestGR.setValue(
        'accepted_on',
        new GlideDateTime()
      );

    }


    requestGR.update();


    var trainerRequestGR =
      new GlideRecord(
        REQUEST_TRAINER_TABLE
      );


    var trainerRequestField =
      resolveField(
        trainerRequestGR,
        ['request'],
        ['Request']
      );


    var trainerRequestTrainerField =
      resolveField(
        trainerRequestGR,
        ['trainer'],
        ['Trainer']
      );


    if (
      trainerRequestField
    ) {

      trainerRequestGR.addQuery(
        trainerRequestField,
        requestSysId
      );

      if (
        trainerRequestTrainerField
      ) {

        trainerRequestGR.addQuery(
          trainerRequestTrainerField,
          trainerSysId
        );

      }

      trainerRequestGR.setLimit(1);
      trainerRequestGR.query();


      if (
        trainerRequestGR.next()
      ) {

        if (
          trainerRequestGR.isValidField(
            'response'
          )
        ) {

          trainerRequestGR.setValue(
            'response',
            'Accepted'
          );

        }


        if (
          trainerRequestGR.isValidField(
            'response_on'
          )
        ) {

          trainerRequestGR.setValue(
            'response_on',
            new GlideDateTime()
          );

        }


        trainerRequestGR.update();

      }

    }


    availabilityGR.setValue(
      availabilityStatusField,
      'Booked'
    );


    availabilityGR.update();


    data.acceptSuccess =
      true;

    data.acceptMessage =
      'Student request accepted and interview scheduled.';

  }


  /* =========================================================
     QR VERIFICATION
     ========================================================= */

  function verifyQR() {

    data.verifySuccess =
      false;

    data.verifyMessage =
      '';


    var interviewSysId =
      clean(
        input.interview
      );


    var enteredToken =
      clean(
        input.token
      );


    if (
      !interviewSysId ||
      !enteredToken
    ) {

      data.verifyMessage =
        'Interview and QR token are required.';

      return;

    }


    var gr =
      new GlideRecord(
        MOCK_INTERVIEW_TABLE
      );


    if (
      !gr.get(
        interviewSysId
      )
    ) {

      data.verifyMessage =
        'Mock Interview could not be found.';

      return;

    }


    var trainerField =
      resolveField(
        gr,
        [
          'trainer_reference',
          'trainer'
        ],
        [
          'Trainer Reference',
          'Trainer'
        ]
      );


    var qrField =
      resolveField(
        gr,
        ['qr_code'],
        ['QR Code']
      );


    var qrStatusField =
      resolveField(
        gr,
        ['qr_status'],
        ['QR Status']
      );


    var attendanceField =
      resolveField(
        gr,
        ['attendance_status'],
        ['Attendance Status']
      );


    if (
      !trainerField ||
      !qrField ||
      !qrStatusField ||
      !attendanceField
    ) {

      data.verifyMessage =
        'QR or attendance fields are missing.';

      return;

    }


    if (
      gr.getValue(
        trainerField
      ) != trainerSysId
    ) {

      data.verifyMessage =
        'This interview does not belong to the current trainer.';

      return;

    }


    var actualToken =
      extractQRToken(
        gr.getValue(
          qrField
        )
      );


    if (
      !actualToken ||
      actualToken.toUpperCase() !=
      enteredToken.toUpperCase()
    ) {

      data.verifyMessage =
        'Invalid QR token.';

      return;

    }


    gr.setValue(
      qrStatusField,
      'Scanned'
    );


    gr.setValue(
      attendanceField,
      'Present'
    );


    if (
      !gr.update()
    ) {

      data.verifyMessage =
        'Attendance could not be updated.';

      return;

    }


    data.verifySuccess =
      true;

    data.verifyMessage =
      'QR verified successfully. Attendance marked Present.';

  }


  /* =========================================================
     MARK INTERVIEW COMPLETED
     ========================================================= */

  function markCompleted() {

    data.completeSuccess =
      false;

    data.completeMessage =
      '';


    var interviewSysId =
      clean(
        input.interview
      );


    /*
     * Receive the selected dropdown value.
     */

    var selectedStatus =
      clean(
        input.status
      );


    if (
      !selectedStatus
    ) {

      selectedStatus =
        'Completed';

    }


    if (
      !interviewSysId
    ) {

      data.completeMessage =
        'Interview record is missing.';

      return;

    }


    /*
     * Only Completed can be submitted.
     */

    if (
      selectedStatus !=
      'Completed'
    ) {

      data.completeMessage =
        'Please select Completed as the interview status.';

      return;

    }


    var gr =
      new GlideRecord(
        MOCK_INTERVIEW_TABLE
      );


    if (
      !gr.get(
        interviewSysId
      )
    ) {

      data.completeMessage =
        'Mock Interview was not found.';

      return;

    }


    var trainerField =
      resolveField(
        gr,
        [
          'trainer_reference',
          'trainer'
        ],
        [
          'Trainer Reference',
          'Trainer'
        ]
      );


    var attendanceField =
      resolveField(
        gr,
        ['attendance_status'],
        ['Attendance Status']
      );


    var qrStatusField =
      resolveField(
        gr,
        ['qr_status'],
        ['QR Status']
      );


    var statusField =
      resolveField(
        gr,
        ['interview_status'],
        ['Interview Status']
      );


    if (
      !trainerField ||
      !statusField
    ) {

      data.completeMessage =
        'Mock Interview status fields are missing.';

      return;

    }


    /*
     * Verify trainer ownership.
     */

    if (
      gr.getValue(
        trainerField
      ) != trainerSysId
    ) {

      data.completeMessage =
        'This interview does not belong to the current trainer.';

      return;

    }


    /*
     * The QR has ALREADY been scanned in the existing workflow.
     *
     * Accept the record when either:
     *   QR Status = Scanned
     * OR
     *   Attendance Status = Present
     *
     * This also handles ServiceNow choice fields whose internal
     * values may be lowercase while the display value is uppercase.
     *
     * There is NO second Verify QR action here.
     */

    var attendanceValue =
      attendanceField
        ? clean(
            gr.getValue(
              attendanceField
            )
          ).toLowerCase()
        : '';


    var attendanceDisplay =
      attendanceField
        ? clean(
            gr.getDisplayValue(
              attendanceField
            )
          ).toLowerCase()
        : '';


    var qrStatusValue =
      qrStatusField
        ? clean(
            gr.getValue(
              qrStatusField
            )
          ).toLowerCase()
        : '';


    var qrStatusDisplay =
      qrStatusField
        ? clean(
            gr.getDisplayValue(
              qrStatusField
            )
          ).toLowerCase()
        : '';


    var attendancePresent =
      attendanceValue ==
        'present'
      ||
      attendanceDisplay ==
        'present';


    var qrAlreadyScanned =
      qrStatusValue ==
        'scanned'
      ||
      qrStatusDisplay ==
        'scanned';


    if (
      !attendancePresent &&
      !qrAlreadyScanned
    ) {

      data.completeMessage =
        'The interview QR must be scanned before completing the interview.';

      return;

    }


    /*
     * Only Scheduled -> Completed.
     */

    var currentValue =
      clean(
        gr.getValue(
          statusField
        )
      );


    var currentDisplay =
      clean(
        gr.getDisplayValue(
          statusField
        )
      );


    if (
      currentValue !=
      'Scheduled'
      &&
      currentDisplay !=
      'Scheduled'
    ) {

      data.completeMessage =
        'Only Scheduled interviews can be marked completed.';

      return;

    }


    /*
     * ACTUAL DATABASE UPDATE
     */

    gr.setValue(
      statusField,
      'Completed'
    );


    if (
      !gr.update()
    ) {

      data.completeMessage =
        'Interview status could not be updated.';

      return;

    }


    data.completeSuccess =
      true;


    data.completeMessage =
      'Interview status updated to Completed.';

  }


  /* =========================================================
     FEEDBACK
     ========================================================= */

  function submitFeedback() {

    data.feedbackSuccess =
      false;

    data.feedbackMessage =
      '';


    var mockSysId =
      clean(
        input.interview
      );


    var technicalScore =
      parseScore(
        input.technicalScore
      );


    var communicationScore =
      parseScore(
        input.communicationScore
      );


    var problemSolvingScore =
      parseScore(
        input.problemSolvingScore
      );


    var strengths =
      clean(
        input.strengths
      );


    var improvementAreas =
      clean(
        input.improvementAreas
      );


    var recommendation =
      clean(
        input.recommendation
      );


    if (
      !mockSysId
    ) {

      data.feedbackMessage =
        'Interview record is missing.';

      return;

    }


    if (
      technicalScore === null ||
      communicationScore === null ||
      problemSolvingScore === null
    ) {

      data.feedbackMessage =
        'Please provide all performance scores from 0 to 100.';

      return;

    }


    var mockGR =
      new GlideRecord(
        MOCK_INTERVIEW_TABLE
      );


    if (
      !mockGR.get(
        mockSysId
      )
    ) {

      data.feedbackMessage =
        'Mock Interview was not found.';

      return;

    }


    var mockTrainerField =
      resolveField(
        mockGR,
        [
          'trainer_reference',
          'trainer'
        ],
        [
          'Trainer Reference',
          'Trainer'
        ]
      );


    var mockStudentField =
      resolveField(
        mockGR,
        [
          'student_reference',
          'student'
        ],
        [
          'Student Reference',
          'Student'
        ]
      );


    var mockStatusField =
      resolveField(
        mockGR,
        ['interview_status'],
        ['Interview Status']
      );


    if (
      !mockTrainerField ||
      !mockStudentField ||
      !mockStatusField
    ) {

      data.feedbackMessage =
        'Mock Interview fields are not configured.';

      return;

    }


    if (
      mockGR.getValue(
        mockTrainerField
      ) != trainerSysId
    ) {

      data.feedbackMessage =
        'This interview does not belong to the current trainer.';

      return;

    }


    if (
      mockGR.getValue(
        mockStatusField
      ) != 'Completed'
    ) {

      data.feedbackMessage =
        'Feedback is available only after the interview is completed.';

      return;

    }


    var feedbackGR =
      new GlideRecord(
        FEEDBACK_TABLE
      );


    var feedbackInterviewField =
      resolveField(
        feedbackGR,
        ['interview_reference'],
        ['Interview Reference']
      );


    var feedbackStudentField =
      resolveField(
        feedbackGR,
        ['student_reference'],
        ['Student Reference']
      );


    var feedbackTrainerField =
      resolveField(
        feedbackGR,
        ['trainer_reference'],
        ['Trainer Reference']
      );


    var technicalField =
      resolveField(
        feedbackGR,
        ['technical_score'],
        ['Technical Score']
      );


    var communicationField =
      resolveField(
        feedbackGR,
        ['communication_score'],
        ['Communication Score']
      );


    var problemSolvingField =
      resolveField(
        feedbackGR,
        ['problem_solving_score'],
        ['Problem Solving Score']
      );


    var overallField =
      resolveField(
        feedbackGR,
        ['overall_score'],
        ['Overall Score']
      );


    if (
      !feedbackInterviewField ||
      !feedbackStudentField ||
      !feedbackTrainerField ||
      !technicalField ||
      !communicationField ||
      !problemSolvingField ||
      !overallField
    ) {

      data.feedbackMessage =
        'Interview Feedback fields are missing.';

      return;

    }


    var existing =
      new GlideRecord(
        FEEDBACK_TABLE
      );


    existing.addQuery(
      feedbackInterviewField,
      mockSysId
    );


    existing.setLimit(1);
    existing.query();


    var feedbackSysId;


    if (
      existing.next()
    ) {

      feedbackSysId =
        existing.getUniqueValue();

      feedbackGR =
        existing;

    } else {

      feedbackGR.initialize();


      var feedbackIdField =
        resolveField(
          feedbackGR,
          ['feedback_id'],
          ['Feedback ID']
        );


      if (
        feedbackIdField
      ) {

        feedbackGR.setValue(
          feedbackIdField,
          generateFeedbackId()
        );

      }


      feedbackGR.setValue(
        feedbackInterviewField,
        mockSysId
      );


      feedbackGR.setValue(
        feedbackStudentField,
        mockGR.getValue(
          mockStudentField
        )
      );


      feedbackGR.setValue(
        feedbackTrainerField,
        trainerSysId
      );

    }


    var overallScore =
      Math.round(
        (
          technicalScore +
          communicationScore +
          problemSolvingScore
        ) / 3
      );


    feedbackGR.setValue(
      technicalField,
      technicalScore
    );


    feedbackGR.setValue(
      communicationField,
      communicationScore
    );


    feedbackGR.setValue(
      problemSolvingField,
      problemSolvingScore
    );


    feedbackGR.setValue(
      overallField,
      overallScore
    );


    var strengthsField =
      resolveField(
        feedbackGR,
        ['strengths'],
        ['Strengths']
      );


    var improvementField =
      resolveField(
        feedbackGR,
        ['improvement_areas'],
        ['Improvement Areas']
      );


    var recommendationField =
      resolveField(
        feedbackGR,
        ['recommendation'],
        ['Recommendation']
      );


    if (
      strengthsField
    ) {

      feedbackGR.setValue(
        strengthsField,
        strengths
      );

    }


    if (
      improvementField
    ) {

      feedbackGR.setValue(
        improvementField,
        improvementAreas
      );

    }


    if (
      recommendationField
    ) {

      feedbackGR.setValue(
        recommendationField,
        recommendation
      );

    }


    if (
      feedbackSysId
    ) {

      feedbackGR.update();

    } else {

      feedbackGR.insert();

    }


    data.feedbackSuccess =
      true;

    data.feedbackMessage =
      'Interview feedback saved successfully.';

  }


  /* =========================================================
     HELPER: AVAILABILITY IDS
     ========================================================= */

  function getTrainerAvailabilityIds() {

    var ids = [];


    var gr =
      new GlideRecord(
        AVAILABILITY_TABLE
      );


    var trainerField =
      resolveField(
        gr,
        [
          'trainer',
          'trainer_reference'
        ],
        ['Trainer']
      );


    if (!trainerField) {

      return ids;

    }


    gr.addQuery(
      trainerField,
      trainerSysId
    );


    gr.query();


    while (
      gr.next()
    ) {

      ids.push(
        gr.getUniqueValue()
      );

    }


    return ids;

  }


  /* =========================================================
     AVAILABILITY OBJECT
     ========================================================= */

  function makeAvailabilityObject(
    gr
  ) {

    return {

      sys_id:
        gr.getUniqueValue(),

      availabilityId:
        getSafe(
          gr,
          ['availability_id'],
          ['Availability ID']
        ),

      interviewType:
        getSafe(
          gr,
          ['interview_type'],
          ['Interview Type']
        ),

      skillArea:
        getSafe(
          gr,
          ['skill_area'],
          ['Skill Area']
        ),

      interviewDate:
        formatDate(
          getSafe(
            gr,
            ['available_date'],
            ['Available Date']
          )
        ),

      startTime:
        formatTime(
          getSafe(
            gr,
            ['start_time'],
            ['Start Time']
          )
        ),

      endTime:
        formatTime(
          getSafe(
            gr,
            ['end_time'],
            ['End Time']
          )
        )

    };

  }


  /* =========================================================
     REQUEST OBJECT
     ========================================================= */

  function makeRequestObject(
    gr
  ) {

    var studentField =
      resolveField(
        gr,
        ['student_reference'],
        ['Student']
      );


    var availabilityField =
      resolveField(
        gr,
        ['selected_availability'],
        ['Selected Availability']
      );


    var student =
      getStudent(
        studentField
          ? gr.getValue(
              studentField
            )
          : ''
      );


    var availability =
      null;


    if (
      availabilityField
    ) {

      var availabilityId =
        gr.getValue(
          availabilityField
        );


      if (
        availabilityId
      ) {

        var availabilityGR =
          new GlideRecord(
            AVAILABILITY_TABLE
          );


        if (
          availabilityGR.get(
            availabilityId
          )
        ) {

          availability =
            makeAvailabilityObject(
              availabilityGR
            );

        }

      }

    }


    return {

      sys_id:
        gr.getUniqueValue(),

      requestId:
        getSafe(
          gr,
          ['request_id'],
          ['Request ID']
        ),

      studentName:
        student.name,

      studentId:
        student.id,

      initials:
        getInitials(
          student.name
        ),

      interviewType:
        availability
          ? availability.interviewType
          : 'Mock Interview',

      skillArea:
        availability
          ? availability.skillArea
          : '',

      interviewDate:
        availability
          ? availability.interviewDate
          : '',

      startTime:
        availability
          ? availability.startTime
          : '',

      endTime:
        availability
          ? availability.endTime
          : ''

    };

  }


  /* =========================================================
     MOCK INTERVIEW OBJECT
     ========================================================= */

  function makeMockObject(
    gr
  ) {

    var studentField =
      resolveField(
        gr,
        [
          'student_reference',
          'student'
        ],
        [
          'Student Reference',
          'Student'
        ]
      );


    var trainerField =
      resolveField(
        gr,
        [
          'trainer_reference',
          'trainer'
        ],
        [
          'Trainer Reference',
          'Trainer'
        ]
      );


    var student =
      getStudent(
        studentField
          ? gr.getValue(
              studentField
            )
          : ''
      );


    var trainerName =
      data.trainer.name;


    var trainerId =
      data.trainer.id;


    if (
      trainerField
    ) {

      var refTrainer =
        new GlideRecord(
          TRAINER_TABLE
        );


      if (
        refTrainer.get(
          gr.getValue(
            trainerField
          )
        )
      ) {

        trainerName =
          getSafe(
            refTrainer,
            ['trainer_name'],
            ['Trainer Name']
          ) ||
          trainerName;


        trainerId =
          getSafe(
            refTrainer,
            ['trainer_id'],
            ['Trainer ID']
          ) ||
          trainerId;

      }

    }


    return {

      sys_id:
        gr.getUniqueValue(),

      interviewId:
        getSafe(
          gr,
          ['interview_id'],
          ['Interview ID']
        ),

      studentName:
        student.name,

      studentId:
        student.id,

      initials:
        getInitials(
          student.name
        ),

      trainerName:
        trainerName,

      trainerId:
        trainerId,

      interviewType:
        getSafe(
          gr,
          ['interview_type'],
          ['Interview Type']
        ),

      interviewDate:
        formatDate(
          getSafe(
            gr,
            ['interview_date'],
            ['Interview Date']
          )
        ),

      startTime:
        formatTime(
          getSafe(
            gr,
            ['start_time'],
            ['Start Time']
          )
        ),

      endTime:
        formatTime(
          getSafe(
            gr,
            ['end_time'],
            ['End Time']
          )
        ),

      qrCode:
        getSafe(
          gr,
          ['qr_code'],
          ['QR Code']
        ),

      qrStatus:
        getSafe(
          gr,
          ['qr_status'],
          ['QR Status']
        ),

      attendanceStatus:
        getSafe(
          gr,
          ['attendance_status'],
          ['Attendance Status']
        ),

      interviewStatus:
        getSafe(
          gr,
          ['interview_status'],
          ['Interview Status']
        )

    };

  }


  /* =========================================================
     STUDENT
     ========================================================= */

  function getStudent(
    sysId
  ) {

    var result = {
      id: '',
      name: 'Student'
    };


    if (!sysId) {

      return result;

    }


    var gr =
      new GlideRecord(
        STUDENT_TABLE
      );


    if (
      !gr.get(
        sysId
      )
    ) {

      return result;

    }


    result.id =
      getSafe(
        gr,
        ['student_id'],
        ['Student ID']
      ) ||
      gr.getUniqueValue();


    result.name =
      getSafe(
        gr,
        ['student_name'],
        ['Student Name']
      ) ||
      gr.getDisplayValue();


    return result;

  }


  /* =========================================================
     VERIFIED COUNT
     ========================================================= */

  function countVerified() {

    var gr =
      new GlideRecord(
        MOCK_INTERVIEW_TABLE
      );


    var trainerField =
      resolveField(
        gr,
        [
          'trainer_reference',
          'trainer'
        ],
        [
          'Trainer Reference',
          'Trainer'
        ]
      );


    var qrStatusField =
      resolveField(
        gr,
        ['qr_status'],
        ['QR Status']
      );


    if (
      !trainerField ||
      !qrStatusField
    ) {

      return 0;

    }


    gr.addQuery(
      trainerField,
      trainerSysId
    );


    gr.addQuery(
      qrStatusField,
      'Scanned'
    );


    gr.query();


    var count = 0;


    while (
      gr.next()
    ) {

      count++;

    }


    return count;

  }


  /* =========================================================
     QR
     ========================================================= */

  function generateQRToken() {

    return (
      'C360-MI-' +
      String(
        gs.generateGUID()
      )
      .substring(
        0,
        12
      )
      .toUpperCase()
    );

  }


  function extractQRToken(
    qrValue
  ) {

    if (!qrValue) {

      return '';

    }


    var text =
      String(
        qrValue
      );


    var marker =
      'data=';


    var index =
      text.indexOf(
        marker
      );


    if (
      index < 0
    ) {

      return '';

    }


    var token =
      text.substring(
        index + marker.length
      );


    var amp =
      token.indexOf(
        '&'
      );


    if (
      amp >= 0
    ) {

      token =
        token.substring(
          0,
          amp
        );

    }


    try {

      token =
        decodeURIComponent(
          token
        );

    } catch (
      ignore
    ) {}


    return clean(
      token
    );

  }


  /* =========================================================
     ID HELPERS
     ========================================================= */

  function generateAvailabilityId() {

    return (
      'TRA' +
      String(
        new GlideDateTime()
          .getNumericValue()
      ).slice(-7)
    );

  }


  function generateInterviewId() {

    return (
      'INT' +
      String(
        new GlideDateTime()
          .getNumericValue()
      ).slice(-7)
    );

  }


  function generateFeedbackId() {

    return (
      'FDB' +
      String(
        new GlideDateTime()
          .getNumericValue()
      ).slice(-7)
    );

  }


  /* =========================================================
     FIELD HELPERS
     ========================================================= */

  function resolveField(
    gr,
    candidates,
    labels
  ) {

    var i;


    for (
      i = 0;
      i < candidates.length;
      i++
    ) {

      if (
        gr.isValidField(
          candidates[i]
        )
      ) {

        return candidates[i];

      }

    }


    if (
      labels &&
      labels.length
    ) {

      var dictionaryGR =
        new GlideRecord(
          'sys_dictionary'
        );


      dictionaryGR.addQuery(
        'name',
        gr.getTableName()
      );


      dictionaryGR.addQuery(
        'column_label',
        'IN',
        labels.join(',')
      );


      dictionaryGR.addNotNullQuery(
        'element'
      );


      dictionaryGR.setLimit(1);
      dictionaryGR.query();


      if (
        dictionaryGR.next()
      ) {

        return dictionaryGR.getValue(
          'element'
        );

      }

    }


    return '';

  }


  function getSafe(
    gr,
    candidates,
    labels
  ) {

    var field =
      resolveField(
        gr,
        candidates,
        labels
      );


    if (!field) {

      return '';

    }


    return String(
      gr.getValue(
        field
      ) || ''
    );

  }


  /* =========================================================
     DATE / TIME
     ========================================================= */

  function normalizeDate(
    value
  ) {

    if (!value) {

      return '';

    }


    return String(
      value
    ).substring(
      0,
      10
    );

  }


  function formatDate(
    value
  ) {

    return normalizeDate(
      value
    );

  }


  function normalizeTime(
    value
  ) {

    if (!value) {

      return '';

    }


    var text =
      String(
        value
      ).trim();


    if (
      text.length == 5
    ) {

      return text + ':00';

    }


    return text.substring(
      0,
      8
    );

  }


  function formatTime(
    value
  ) {

    if (!value) {

      return '';

    }


    return String(
      value
    ).substring(
      0,
      5
    );

  }


  function timeToMinutes(
    value
  ) {

    var text =
      normalizeTime(
        value
      );


    if (!text) {

      return 0;

    }


    var p =
      text.split(':');


    return (
      parseInt(
        p[0],
        10
      ) * 60
      +
      parseInt(
        p[1],
        10
      )
    );

  }


  /* =========================================================
     GENERAL
     ========================================================= */

  function parseScore(
    value
  ) {

    if (
      value === null ||
      typeof value === 'undefined' ||
      value === ''
    ) {

      return null;

    }


    var score =
      parseInt(
        value,
        10
      );


    if (
      isNaN(score) ||
      score < 0 ||
      score > 100
    ) {

      return null;

    }


    return score;

  }


  function clean(
    value
  ) {

    return String(
      value || ''
    ).trim();

  }


  function getInitials(
    name
  ) {

    if (!name) {

      return 'TR';

    }


    var parts =
      String(
        name
      )
      .trim()
      .split(/\s+/);


    if (
      parts.length == 1
    ) {

      return parts[0]
        .substring(
          0,
          2
        )
        .toUpperCase();

    }


    return (
      parts[0].charAt(0) +
      parts[
        parts.length - 1
      ].charAt(0)
    ).toUpperCase();

  }

})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
